const PAIRS = [
[7176075, 7176129, 'Save changes'],
[7176119, 7176135, 'Change password'],
[7176095, 7176099, 'Reactivate subscription'],
[7176111, 7176057, '7-day full access']
];
const DELETE_EMPTY = [7174055];

const byId = {};
for (const p of $input.all()) {
  const b = (p.json && p.json.body) || {};
  for (const t of (Array.isArray(b.data) ? b.data : [])) { byId[t.id] = t; }
}
function fill(t) {
  const m = {};
  let n = 0;
  for (const tr of ((t && t.translations) || [])) {
    const v = String(tr.translation || '').trim();
    if (v) { m[tr.langId] = v; n++; }
  }
  return { map: m, n: n };
}

const updates = [];
const audit = [];
const dels = [];
for (const pr of PAIRS) {
  const keep = byId[pr[0]];
  const drop = byId[pr[1]];
  if (!keep || !drop) { audit.push({ term: pr[2], error: 'id not found' }); continue; }
  const A = fill(keep), B = fill(drop);
  const richerIsDrop = B.n > A.n;
  const out = {};
  const langs = {};
  for (const l in A.map) langs[l] = 1;
  for (const l in B.map) langs[l] = 1;
  let added = 0, overridden = 0;
  for (const l in langs) {
    const a = A.map[l], b = B.map[l];
    let v = a;
    if (!a && b) { v = b; added++; }
    else if (a && b && a !== b && richerIsDrop) { v = b; overridden++; }
    if (v) out[l] = v;
  }
  const trs = [];
  for (const l in out) { trs.push({ langId: parseInt(l, 10), translation: out[l] }); }
  updates.push({ id: pr[0], translations: trs });
  audit.push({ term: pr[2], keep_id: pr[0], keep_langs: A.n, drop_id: pr[1], drop_langs: B.n, merged_langs: trs.length, filled_gaps: added, overridden_from_richer: overridden, es: out[1056] || '' });
  dels.push(pr[1]);
}
for (const d of DELETE_EMPTY) { dels.push(d); }

return [{ json: { audit: audit, deletes: dels, update_body: { terms: updates }, delete_body: { terms: dels },
  update_url: 'https://api.lokalise.com/api2/projects/46552447679363c70f7ef8.58193285/glossary-terms',
  delete_url: 'https://api.lokalise.com/api2/projects/46552447679363c70f7ef8.58193285/glossary-terms' } }];

const plan = $('Build Merge').first().json;
const u = $('Merge Translations').first().json || {};
const d = $input.first().json || {};
return [{ json: {
  audit: plan.audit,
  deleted_ids: plan.deletes,
  merge_status: u.statusCode,
  merge_body: JSON.stringify(u.body || {}).slice(0, 220),
  delete_status: d.statusCode,
  delete_body: JSON.stringify(d.body || {}).slice(0, 220)
} }];
